<script>(function(){document.querySelectorAll('[data-edit]').forEach(function(btn){btn.addEventListener('click',function(){var n=this.dataset.edit;document.querySelectorAll('.inline-form.open').forEach(function(f){f.classList.remove('open')});document.getElementById('form-'+n)?.classList.add('open');});});document.querySelectorAll('[data-cancel]').forEach(function(btn){btn.addEventListener('click',function(){document.getElementById('form-'+this.dataset.cancel)?.classList.remove('open');});});var file=document.getElementById('logo-file');if(file)file.addEventListener('change',function(){var f=this.files&&this.files[0];if(!f)return;var img=document.getElementById('logo-preview'),ph=document.getElementById('logo-placeholder');img.src=URL.createObjectURL(f);img.style.display='block';if(ph)ph.style.display='none';});})();</script>
